def semver_sort(versions):
    def parse_version(version):
        # Split off build metadata (after '+')
        if '+' in version:
            version_part, build = version.split('+', 1)
        else:
            version_part = version
            build = ''

        # Split off pre-release (after '-')
        if '-' in version_part:
            core, prerelease = version_part.split('-', 1)
        else:
            core = version_part
            prerelease = None

        # Parse core version (MAJOR.MINOR.PATCH)
        parts = core.split('.')
        major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])

        # Parse pre-release identifiers
        if prerelease is not None:
            prerelease_parts = prerelease.split('.')
            # Convert to tuple of comparable values
            prerelease_tuple = tuple(
                (0, int(part)) if part.isdigit() else (1, part)
                for part in prerelease_parts
            )
        else:
            # No pre-release sorts after pre-release
            prerelease_tuple = None

        return (major, minor, patch, prerelease_tuple)

    def sort_key(item):
        index, version = item
        major, minor, patch, prerelease_tuple = parse_version(version)

        # For sorting: versions without pre-release sort after those with pre-release
        # So we use (major, minor, patch, has_prerelease, prerelease_tuple, index)
        # has_prerelease=0 if prerelease_tuple is not None, 1 otherwise (reverse order)
        if prerelease_tuple is not None:
            return (major, minor, patch, 0, prerelease_tuple, index)
        else:
            return (major, minor, patch, 1, (), index)

    # Enumerate to maintain stable sort (original order for equal precedence)
    indexed_versions = [(i, v) for i, v in enumerate(versions)]
    sorted_versions = sorted(indexed_versions, key=sort_key)

    return [v for i, v in sorted_versions]

